import{_ as t,o as e,c as n,a5 as i}from"./chunks/framework.CsGesDJn.js";const p=JSON.parse('{"title":"UC — Upgrade Plan","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subscription-billing/3-9-1-upgrade-plan/spec.md","filePath":"feature/subscription-billing/3-9-1-upgrade-plan/spec.md"}'),r={name:"feature/subscription-billing/3-9-1-upgrade-plan/spec.md"};function o(s,a,c,h,l,d){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="uc-—-upgrade-plan" tabindex="-1">UC — Upgrade Plan <a class="header-anchor" href="#uc-—-upgrade-plan" aria-label="Permalink to &quot;UC — Upgrade Plan&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td>FR Code</td><td>3.9.1</td></tr><tr><td>Feature</td><td>Upgrade Plan</td></tr><tr><td>Domain</td><td>Subscription (FR 3.9)</td></tr><tr><td>Role</td><td>USER</td></tr><tr><td>Version</td><td>2.0 (V2 — nghiệp vụ mới, 2026-09-14)</td></tr><tr><td>Trạng thái tài liệu</td><td>Draft — BA confirmed, chưa code</td></tr></tbody></table><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>User mới mặc định gói Basic; upgrade lên Pro/Enterprise để tạo nhiều Workspace, nhiều credit AI, và dùng tính năng nâng cao.</p><h2 id="_2-user-story" tabindex="-1">2. User Story <a class="header-anchor" href="#_2-user-story" aria-label="Permalink to &quot;2. User Story&quot;">​</a></h2><p>Là một User, tôi muốn upgrade lên Pro/Enterprise, để mở khóa thêm Workspace và credit AI cho Agency của tôi.</p><h2 id="_3-acceptance-criteria" tabindex="-1">3. Acceptance Criteria <a class="header-anchor" href="#_3-acceptance-criteria" aria-label="Permalink to &quot;3. Acceptance Criteria&quot;">​</a></h2><ul><li>Danh sách Plan (Basic/Pro/Enterprise) hiển thị rõ giới hạn: số Workspace tối đa, credit AI/tháng, tính năng nâng cao.</li><li>Chọn Plan → chuyển sang Make Payment (FR 3.9.3) để thanh toán.</li><li>Upgrade thành công → cập nhật ngay giới hạn Workspace/credit cho toàn bộ Agency của User (Plan gắn cấp User/Owner, xem <a href="./../../../BA/08-subscription-billing.html">08-subscription-billing.md</a>).</li></ul><h2 id="_4-ui-ux" tabindex="-1">4. UI / UX <a class="header-anchor" href="#_4-ui-ux" aria-label="Permalink to &quot;4. UI / UX&quot;">​</a></h2><ul><li>Trang <code>/settings/subscription</code>.</li></ul><h2 id="_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" tabindex="-1">5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật) <a class="header-anchor" href="#_5-api-contract-đe-xuat-can-xac-nhan-khi-thiet-ke-ky-thuat" aria-label="Permalink to &quot;5. API Contract (đề xuất, cần xác nhận khi thiết kế kỹ thuật)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/subscriptions/plans</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: [{ &quot;id&quot;, &quot;name&quot;, &quot;maxWorkspaces&quot;, &quot;monthlyCredit&quot;, &quot;price&quot; }] }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>POST /api/v1/subscriptions/upgrade</span></span>
<span class="line"><span>{ &quot;planId&quot;: &quot;string&quot; }</span></span>
<span class="line"><span>→ 200 { &quot;success&quot;: true, &quot;data&quot;: { &quot;paymentUrl&quot; hoặc &quot;transactionId&quot; } }</span></span></code></pre></div><h2 id="_6-error-handling" tabindex="-1">6. Error Handling <a class="header-anchor" href="#_6-error-handling" aria-label="Permalink to &quot;6. Error Handling&quot;">​</a></h2><ul><li>User đã ở Plan cao nhất (Enterprise) → 400 <code>ALREADY_AT_HIGHEST_PLAN</code>.</li></ul><h2 id="_7-edge-cases" tabindex="-1">7. Edge Cases <a class="header-anchor" href="#_7-edge-cases" aria-label="Permalink to &quot;7. Edge Cases&quot;">​</a></h2><ul><li>Upgrade thành công nhưng thanh toán chưa hoàn tất → Plan chỉ áp dụng SAU khi Make Payment xác nhận thành công (không active trước khi thanh toán xong).</li></ul><h2 id="_8-definition-of-done" tabindex="-1">8. Definition of Done <a class="header-anchor" href="#_8-definition-of-done" aria-label="Permalink to &quot;8. Definition of Done&quot;">​</a></h2><ul><li>Upgrade hoạt động, giới hạn mới áp dụng đúng ngay sau thanh toán thành công.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Không có.</li></ul><h2 id="tham-chieu-ba" tabindex="-1">Tham chiếu BA <a class="header-anchor" href="#tham-chieu-ba" aria-label="Permalink to &quot;Tham chiếu BA&quot;">​</a></h2><p><a href="./../../../BA/08-subscription-billing.html">08-subscription-billing.md</a></p>`,22)])])}const g=t(r,[["render",o]]);export{p as __pageData,g as default};
